package l1j.server.server.model; public class L1Object {public int id=1,map=4,x=100,y=100; public int getId(){return id;} public short getMapId(){return(short)map;} public Location getLocation(){return new Location(x,y);} public static class Location {final int x,y; Location(int x,int y){this.x=x;this.y=y;} public boolean isInScreen(Location p){return Math.abs(x-p.x)<=18&&Math.abs(y-p.y)<=18;} public boolean isSamePoint(Location p){return x==p.x&&y==p.y;} public int getTileLineDistance(Location p){return Math.max(Math.abs(x-p.x),Math.abs(y-p.y));}}}
